import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';

const source = fs.readFileSync('docs/javascripts/observatory-status.js', 'utf8');
const relaySource = fs.readFileSync('infrastructure/telemetry-relay/app.py', 'utf8');
const publisherSource = fs.readFileSync('scripts/telemetry/Publish-EagleHealthTelemetry.ps1', 'utf8');

function makeElement(){return{textContent:''};}
function makeDocument(){const byKey=new Map();return{baseURI:'https://example.test/status/',readyState:'complete',querySelector(){return makeElement();},querySelectorAll(selector){const match=selector.match(/data-eagle-health=\"([^\"]+)\"/);if(!match)return[];if(!byKey.has(match[1]))byKey.set(match[1],[makeElement()]);return byKey.get(match[1]);},addEventListener(){},values:byKey};}
function runWithFetch(fetchImpl,now=Date.parse('2026-09-04T16:38:00Z')){const document=makeDocument(),timers=[];const context={console:{warn(){},log(){}},document,window:{document$:null,DSG:null,setInterval(fn){timers.push(fn);return 1;}},fetch:fetchImpl,URL,Date:class extends Date{static now(){return now;}},clearInterval(){},setInterval(fn){timers.push(fn);return 1;}};vm.createContext(context);vm.runInContext(source,context);return{document,timers};}
const current={schema_version:'1.0',component:'DSG.EagleHealthPortalProjection',host:'EAGLE30154',observed_at_utc:'2026-09-04T16:37:19.443Z',fresh_until_utc:'2026-09-04T16:39:19.443Z',quality:'CURRENT',source_component:'DSG.EagleHostHealthCollector',source_correlation_id:'11111111-1111-1111-1111-111111111111',summary:{state:'UNKNOWN',reason:'POLICY_NOT_ACTIVATED'},signals:{cpu:{state:'OBSERVED',quality:'CURRENT',observed_at_utc:'2026-09-04T16:37:19.443Z',fresh_until_utc:'2026-09-04T16:39:19.443Z',source:'Win32_Processor',cadence_class:'FAST',reason:null,data:{model:'CPU',physical_cores:4,logical_processors:8,load_pct:10}}}};
function response(data,ok=true,status=200){return Promise.resolve({ok,status,json:async()=>data});}
const tick=()=>new Promise(r=>setTimeout(r,0));

await test('G7-D hosted EAGLE projection is preferred over static fallback',async()=>{const calls=[];const {document}=runWithFetch(url=>{calls.push(String(url));if(String(url).includes('/v1/eagle-health'))return response(current);return Promise.reject(new Error('ignore'));});await tick();assert.ok(calls.some(x=>x.includes('/v1/eagle-health')));assert.equal(document.values.get('summary')[0].textContent,'UNKNOWN / POLICY_NOT_ACTIVATED');assert.match(document.values.get('source')[0].textContent,/CLOUD RUN/);});
await test('G7-D static EAGLE projection is used only after hosted failure',async()=>{const calls=[];const {document}=runWithFetch(url=>{calls.push(String(url));if(String(url).includes('/v1/eagle-health'))return Promise.reject(new Error('relay offline'));if(String(url).includes('eagle-health.json'))return response(current);return Promise.reject(new Error('ignore'));});await tick();assert.ok(calls.findIndex(x=>x.includes('/v1/eagle-health'))<calls.findIndex(x=>x.includes('eagle-health.json')));assert.match(document.values.get('source')[0].textContent,/FALLBACK/);});
await test('G7-D stale projection is forced STALE and does not present CPU as current',async()=>{const {document}=runWithFetch(url=>String(url).includes('/v1/eagle-health')?response(current):Promise.reject(new Error('ignore')),Date.parse('2026-09-04T17:00:00Z'));await tick();assert.match(document.values.get('quality')[0].textContent,/STALE/);assert.doesNotMatch(document.values.get('cpu')[0].textContent,/load 10/);});
await test('G7-D malformed hosted and fallback projections fail closed',async()=>{const malformed={...current,component:'WRONG'};const {document}=runWithFetch(url=>String(url).includes('eagle-health')?response(malformed):Promise.reject(new Error('ignore')));await tick();assert.match(document.values.get('quality')[0].textContent,/UNKNOWN/);assert.equal(document.values.get('summary')[0].textContent,'UNKNOWN / POLICY_NOT_ACTIVATED');});
await test('G7-D missing EAGLE transport fails closed without breaking other refresh paths',async()=>{const {document}=runWithFetch(()=>Promise.reject(new Error('offline')));await tick();assert.match(document.values.get('quality')[0].textContent,/UNKNOWN/);});
await test('G7-D browser contains no ingest credential material',()=>{assert.doesNotMatch(source,/Authorization\s*:/i);assert.doesNotMatch(source,/Bearer\s+[A-Za-z0-9]/i);assert.doesNotMatch(source,/DSG_TELEMETRY_INGEST_TOKEN/);});
await test('G7-D relay exposes separate read-only EAGLE channel and no command route',()=>{assert.match(relaySource,/\/v1\/eagle-health/);assert.match(relaySource,/validate_eagle_health/);assert.match(relaySource,/POLICY_NOT_ACTIVATED/);assert.match(relaySource,/automatic_remediation/);assert.doesNotMatch(relaySource,/\/v1\/(command|control|remediate|reboot)/i);});
await test('G7-D EAGLE publisher requires HTTPS and bearer token outside browser',()=>{assert.match(publisherSource,/requires HTTPS/);assert.match(publisherSource,/DSG_TELEMETRY_INGEST_TOKEN/);assert.match(publisherSource,/Idempotency-Key/);assert.match(publisherSource,/source_correlation_id/);});
